#include <stdio.h>

void refill(int *tank) {
    *tank = 100;
}

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main(void) {
    int main_tank = 12, spare = 3;
    refill(&main_tank);
    swap(&main_tank, &spare);
    printf("%d %d\n", main_tank, spare);
    return 0;
}

