void minmax(int a, int b, int c, int *lo, int *hi) {
    *lo = a;
    *hi = a;
    if (b < *lo) *lo = b;
    if (c < *lo) *lo = c;
    if (b > *hi) *hi = b;
    if (c > *hi) *hi = c;
}

int main(void) {
    int a, b, c, lo = 0, hi = 0;
    scanf("%d %d %d", &a, &b, &c);
    minmax(a, b, c, &lo, &hi);
    printf("%d %d\n", lo, hi);
    return 0;
}

