#include <stdio.h>

int count_above(int *arr, int n, int limit) {
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i] > limit) count++;
    }
    return count;
}

int main(void) {
    int n, limit, a[100];
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    scanf("%d", &limit);
    printf("%d\n", count_above(a, n, limit));
    return 0;
}

