#include <stdio.h>

typedef struct {
    char name[20];
    int age;
} Crew;

void birthday(Crew *c) {
    c->age++;
}

int main(void) {
    Crew pilot = {"Mira", 31};
    birthday(&pilot);
    printf("%s is %d\n", pilot.name, pilot.age);
    return 0;
}

